import heapq
import json
import sys

ALLOWED = {'Depends', 'Before', 'After', 'Needs', 'Requires', 'Alias', 'Phony'}


class _ParseError(Exception):
    pass


def _parse(lines):
    blocks = []
    cur = None
    for raw in lines:
        line = raw.strip()
        if not line or line.startswith('#'):
            continue
        if line.startswith('[') and line.endswith(']'):
            continue
        tokens = line.split()
        head = tokens[0]
        if head == 'TARGET':
            if len(tokens) != 2:
                raise _ParseError()
            cur = {'kind': 'T', 'name': tokens[1], 'id': None, 'dirs': []}
            blocks.append(cur)
        elif head == 'OVERRIDE':
            if len(tokens) != 3:
                raise _ParseError()
            cur = {'kind': 'O', 'name': tokens[1], 'id': tokens[2], 'dirs': []}
            blocks.append(cur)
        else:
            if cur is None:
                raise _ParseError()
            if line.count('=') != 1:
                raise _ParseError()
            key, val = line.split('=', 1)
            key = key.strip()
            val = val.strip()
            if key not in ALLOWED:
                raise _ParseError()
            if key == 'Phony':
                if val not in ('yes', 'no'):
                    raise _ParseError()
                cur['dirs'].append(('Phony', val))
            else:
                cur['dirs'].append((key, val.split()))
    return blocks


def _solve(lines):
    blocks = _parse(lines)
    if not blocks:
        return '{"order":[],"cycles":[]}'

    defined = set()
    referenced = set()
    parent = {}

    def find(x):
        parent.setdefault(x, x)
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return
        if ra < rb:
            parent[rb] = ra
        else:
            parent[ra] = rb

    for b in blocks:
        defined.add(b['name'])
        find(b['name'])
        for key, vals in b['dirs']:
            if key == 'Alias':
                for v in vals:
                    referenced.add(v)
                    union(b['name'], v)
            elif key != 'Phony':
                for v in vals:
                    referenced.add(v)

    def canon(x):
        return find(x)

    nodes = set()
    for n in defined | referenced:
        nodes.add(canon(n))

    tblocks = [b for b in blocks if b['kind'] == 'T']
    oblocks = sorted([b for b in blocks if b['kind'] == 'O'], key=lambda b: b['id'])

    adj = {n: set() for n in nodes}
    phony = {}

    for b in tblocks + oblocks:
        u = canon(b['name'])
        for key, vals in b['dirs']:
            if key == 'Phony':
                phony[u] = vals
                continue
            if key == 'Alias':
                continue
            for v in vals:
                cv = canon(v)
                if key in ('Depends', 'After'):
                    adj[cv].add(u)
                else:
                    adj[u].add(cv)

    index = {}
    low = {}
    stack = []
    onstack = set()
    sccs = []
    counter = [0]

    def strong(v):
        index[v] = counter[0]
        low[v] = counter[0]
        counter[0] += 1
        stack.append(v)
        onstack.add(v)
        for w in sorted(adj[v]):
            if w not in index:
                strong(w)
                low[v] = min(low[v], low[w])
            elif w in onstack:
                low[v] = min(low[v], index[w])
        if low[v] == index[v]:
            comp = []
            while True:
                w = stack.pop()
                onstack.discard(w)
                comp.append(w)
                if w == v:
                    break
            sccs.append(sorted(comp))

    sys.setrecursionlimit(max(10000, 10 * len(nodes) + 1000))
    for v in sorted(nodes):
        if v not in index:
            strong(v)

    comp_of = {}
    for i, c in enumerate(sccs):
        for n in c:
            comp_of[n] = i

    cadj = {i: set() for i in range(len(sccs))}
    for u in nodes:
        for v in adj[u]:
            if comp_of[u] != comp_of[v]:
                cadj[comp_of[u]].add(comp_of[v])
    indeg = {i: 0 for i in range(len(sccs))}
    for i in cadj:
        for j in cadj[i]:
            indeg[j] += 1

    heap = [(sccs[i][0], i) for i in range(len(sccs)) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        _, i = heapq.heappop(heap)
        order.extend(sccs[i])
        for j in cadj[i]:
            indeg[j] -= 1
            if indeg[j] == 0:
                heapq.heappush(heap, (sccs[j][0], j))

    cycles = []
    for c in sccs:
        if len(c) >= 2 or (c[0] in adj[c[0]]):
            cycles.append(sorted(c))
    cycles.sort()

    return json.dumps({'order': order, 'cycles': cycles}, separators=(',', ':'))


def solve(lines):
    try:
        return _solve(lines)
    except _ParseError:
        return 'PARSE_ERROR'


if __name__ == '__main__':
    print(solve(sys.stdin.read().splitlines()))
